files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #2a2a2a;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #5a5a5a;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #fb5849;
  --vt-accent-on-deep: #fb5849;
  --vt-line: #e5e0e0;
  font-family: 'Inter', 'Fira Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  scroll-behavior: smooth;
  line-height: 1.6;
}

.root, .root * {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
}

.root :where(p) {
  margin: 0;
}

.root :where(figure) {
  margin: 0;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 3px;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 20;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.logo {
  display: flex;
  align-items: center;
  color: var(--vt-ink);
  font-weight: 700;
  font-size: 1.25rem;
  letter-spacing: 0.02em;
}

.brand {
  display: inline-block;
  height: 36px;
  width: auto;
  color: var(--vt-ink);
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 28px;
}

.navLinks a {
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--vt-ink);
  transition: color 0.2s;
}

.navLinks a:hover {
  color: var(--vt-accent-ink);
}

.hero {
  display: grid;
  grid-template-columns: 5fr 7fr;
  min-height: calc(100vh - 72px);
}

.heroPanel {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 64px 48px;
}

.heroInner {
  width: 100%;
  max-width: 400px;
}

.heroBrand {
  display: block;
  margin-bottom: 28px;
  color: var(--vt-on-accent);
}

.heroTitle {
  font-size: 3rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.01em;
  line-height: 1.05;
}

.heroKicker {
  margin-top: 12px;
  font-size: 0.8125rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  font-weight: 600;
}

.heroButton {
  display: inline-block;
  margin-top: 32px;
  background: var(--vt-surface);
  color: var(--vt-accent-ink);
  padding: 14px 28px;
  border-radius: 4px;
  font-weight: 600;
  font-size: 0.875rem;
  transition: opacity 0.2s;
}

.heroButton:hover {
  opacity: 0.9;
}

.heroSlides {
  display: grid;
  grid-template-columns: repeat(3, 100%);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  min-height: calc(100vh - 72px);
}

.heroSlides::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  scroll-snap-align: start;
  position: relative;
  overflow: hidden;
  min-height: calc(100vh - 72px);
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.about {
  padding: 96px 24px;
}

.aboutGrid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.eyebrow {
  position: relative;
  padding-left: 40px;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--vt-accent-ink);
  margin-bottom: 16px;
}

.eyebrow::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 30px;
  height: 2px;
  background: var(--vt-accent);
  transform: translateY(-50%);
}

.title {
  font-size: 2.25rem;
  font-weight: 900;
  line-height: 1.2;
  color: var(--vt-ink);
  margin-bottom: 24px;
}

.paragraph {
  font-size: 1rem;
  line-height: 1.8;
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.aboutVisual {
  position: relative;
}

.aboutMain {
  border-radius: 8px;
  overflow: hidden;
  border: 1px solid var(--vt-line);
}

.aboutMain img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.aboutThumbs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: -40px;
  padding: 0 24px;
}

.aboutThumbs img {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  border-radius: 8px;
  border: 3px solid var(--vt-surface);
}

.menu {
  background: var(--vt-surface-2);
  padding: 96px 24px;
}

.sectionHead {
  max-width: 1200px;
  margin: 0 auto 64px;
}

.menu .sectionHead {
  text-align: left;
}

.menuRow {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.menuCard {
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 8px;
  overflow: hidden;
}

.menuImage {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.menuNum {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 40px;
  height: 40px;
  border-radius: 4px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8125rem;
  font-weight: 700;
}

.menuBody {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 20px;
}

.menuTitle {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 8px;
}

.menuDesc {
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--vt-ink-soft);
  flex: 1;
  margin-bottom: 16px;
}

.menuLink {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--vt-accent-ink);
}

.menuLink:hover {
  color: var(--vt-ink);
}

.gallery {
  padding: 96px 24px;
}

.gallery .sectionHead {
  text-align: center;
}

.galleryGrid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.galleryItem {
  position: relative;
  border-radius: 8px;
  overflow: hidden;
}

.galleryItem img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  display: block;
  transition: transform 0.4s;
}

.galleryItem:hover img {
  transform: scale(1.03);
}

.galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 600;
}

.contact {
  background: var(--vt-surface-deep);
  padding: 96px 24px;
}

.contactInner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.contact .eyebrow {
  color: var(--vt-accent-on-deep);
}

.contact .eyebrow::before {
  background: var(--vt-accent-on-deep);
}

.contact .title {
  color: var(--vt-on-deep);
}

.contactCard {
  background: var(--vt-surface);
  border-radius: 8px;
  padding: 40px;
}

.contactCardTitle {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 12px;
}

.contactCardText {
  font-size: 1rem;
  line-height: 1.7;
  color: var(--vt-ink-soft);
  margin-bottom: 24px;
}

.footer {
  background: var(--vt-accent);
  padding: 48px 24px;
}

.footerIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}

.footerBrand {
  color: var(--vt-on-accent);
}

.footerText {
  color: var(--vt-on-accent);
  font-size: 0.875rem;
}

@media (max-width: 768px) {
  .navIn {
    height: auto;
    padding: 12px 16px;
    flex-wrap: wrap;
  }

  .logo {
    flex: 1 1 auto;
  }

  .navLinks {
    flex: 1 1 100%;
    order: 3;
    justify-content: center;
    flex-wrap: wrap;
    gap: 12px;
    padding-top: 8px;
  }

  .hero {
    grid-template-columns: 1fr;
    min-height: 0;
  }

  .heroPanel {
    padding: 48px 24px;
  }

  .heroSlides {
    min-height: 260px;
  }

  .heroSlide {
    min-height: 260px;
  }

  .about {
    padding: 64px 16px;
  }

  .aboutGrid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .aboutThumbs {
    margin-top: -32px;
    padding: 0 16px;
    gap: 8px;
  }

  .menu {
    padding: 64px 16px;
  }

  .menuRow {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .gallery {
    padding: 64px 16px;
  }

  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
    gap: 16px;
  }

  .contact {
    padding: 64px 16px;
  }

  .contactInner {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  .contactCard {
    padding: 28px;
  }

  .footer {
    padding: 40px 16px;
  }

  .footerIn {
    flex-direction: column;
    text-align: center;
  }

  .title {
    font-size: 1.75rem;
  }

  .heroTitle {
    font-size: 2.25rem;
  }
}

@media (max-width: 480px) {
  .menuRow,
  .galleryGrid {
    grid-template-columns: 1fr;
  }
}
